package com.slayerprompt;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(SlayerSetupPromptConfig.GROUP)
public interface SlayerSetupPromptConfig extends Config
{
    String GROUP = "slayersetupprompt";

    @ConfigItem(
        keyName = "lastTask",
        name = "Last slayer task",
        description = "Task used to pre-fill the prompt panel when RuneLite cannot detect the current task."
    )
    default String lastTask()
    {
        return "";
    }
}

package com.slayerprompt;

import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.SwingConstants;
import net.runelite.client.ui.PluginPanel;

class SlayerSetupPromptPanel extends PluginPanel
{
    private static final String[] COMMON_TASKS = {
        "",
        "Aberrant spectres",
        "Abyssal demons",
        "Adamant dragons",
        "Ankou",
        "Aviansies",
        "Basilisks",
        "Black demons",
        "Black dragons",
        "Bloodvelds",
        "Blue dragons",
        "Dagannoth",
        "Dust devils",
        "Elves",
        "Fire giants",
        "Gargoyles",
        "Greater demons",
        "Hellhounds",
        "Kalphites",
        "Kurask",
        "Lizardmen",
        "Mithril dragons",
        "Nechryael",
        "Smoke devils",
        "Suqah",
        "Trolls",
        "TzHaar",
        "Vampyres",
        "Wyrms",
        "Wyverns"
    };

    private final JComboBox<String> taskSelector = new JComboBox<>(COMMON_TASKS);
    private final JTextArea promptArea = new JTextArea();

    SlayerSetupPromptPanel(SlayerSetupPromptPlugin plugin, String initialTask)
    {
        super(false);
        setLayout(new BorderLayout(0, 8));
        setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

        taskSelector.setEditable(true);
        taskSelector.setSelectedItem(initialTask == null ? "" : initialTask);
        taskSelector.addActionListener(event -> plugin.refreshPrompt());

        JButton refreshButton = new JButton("Refresh prompt");
        refreshButton.addActionListener(event -> plugin.refreshPrompt());

        JButton copyButton = new JButton("Copy prompt");
        copyButton.addActionListener(event -> copyPrompt());

        JPanel controls = new JPanel(new BorderLayout(0, 6));
        controls.add(new JLabel("Slayer task", SwingConstants.LEFT), BorderLayout.NORTH);
        controls.add(taskSelector, BorderLayout.CENTER);

        JPanel buttons = new JPanel(new BorderLayout(6, 0));
        buttons.add(refreshButton, BorderLayout.CENTER);
        buttons.add(copyButton, BorderLayout.EAST);
        controls.add(buttons, BorderLayout.SOUTH);

        promptArea.setEditable(false);
        promptArea.setLineWrap(true);
        promptArea.setWrapStyleWord(true);
        promptArea.setTabSize(2);
        promptArea.setText("Open your bank, select a task, then refresh or copy the prompt.");

        JScrollPane promptScroll = new JScrollPane(promptArea);
        promptScroll.setPreferredSize(new Dimension(PANEL_WIDTH - 20, 420));

        add(controls, BorderLayout.NORTH);
        add(promptScroll, BorderLayout.CENTER);
    }

    String getSelectedTask()
    {
        Object selectedItem = taskSelector.getEditor().getItem();
        return selectedItem == null ? "" : selectedItem.toString();
    }

    void setSelectedTask(String task)
    {
        taskSelector.setSelectedItem(task);
    }

    void setPrompt(String prompt)
    {
        promptArea.setText(prompt);
        promptArea.setCaretPosition(0);
    }

    private void copyPrompt()
    {
        Toolkit.getDefaultToolkit()
            .getSystemClipboard()
            .setContents(new StringSelection(promptArea.getText()), null);
    }
}

package com.slayerprompt;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

@PluginDescriptor(
    name = "Slayer Setup Prompt",
    description = "Builds a copyable AI prompt for ironman slayer setup planning",
    tags = {"slayer", "ironman", "bank", "gear", "prompt"}
)
public class SlayerSetupPromptPlugin extends Plugin
{
    private static final Pattern ASSIGNED_PATTERN = Pattern.compile(
        "(?i)(?:you(?:'|\\u2019)re assigned to kill|your new task is to kill|assigned to kill)\\s+(.+?)(?:\\.|$)"
    );

    private static final Pattern REMAINING_PATTERN = Pattern.compile(
        "(?i)(?:you(?:'|\\u2019)re still hunting|you still need to kill)\\s+(?:\\d+\\s+)?(.+?)(?:\\.|$)"
    );

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private ClientThread clientThread;

    @Inject
    private ConfigManager configManager;

    @Inject
    private SlayerSetupPromptConfig config;

    @Inject
    private SlayerSetupPromptSnapshotBuilder snapshotBuilder;

    private SlayerSetupPromptPanel panel;
    private NavigationButton navButton;

    @Override
    protected void startUp()
    {
        panel = new SlayerSetupPromptPanel(this, config.lastTask());
        navButton = NavigationButton.builder()
            .tooltip("Slayer Setup Prompt")
            .icon(createIcon())
            .priority(5)
            .panel(panel)
            .build();

        clientToolbar.addNavigation(navButton);
        refreshPrompt();
    }

    @Override
    protected void shutDown()
    {
        clientToolbar.removeNavigation(navButton);
        panel = null;
        navButton = null;
    }

    void refreshPrompt()
    {
        if (panel == null)
        {
            return;
        }

        String task = getSelectedTaskThreadSafe().trim();
        clientThread.invokeLater(() ->
        {
            String prompt = snapshotBuilder.buildPrompt(task);
            SwingUtilities.invokeLater(() ->
            {
                if (panel != null)
                {
                    panel.setPrompt(prompt);
                }
            });
            saveTask(task);
        });
    }

    void updateTask(String task)
    {
        if (panel == null || task == null || task.trim().isEmpty())
        {
            return;
        }

        String cleanedTask = cleanTask(task);
        clientThread.invokeLater(() ->
        {
            String prompt = snapshotBuilder.buildPrompt(cleanedTask);
            SwingUtilities.invokeLater(() ->
            {
                if (panel != null)
                {
                    panel.setSelectedTask(cleanedTask);
                    panel.setPrompt(prompt);
                }
            });
            saveTask(cleanedTask);
        });
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded widgetLoaded)
    {
        if (widgetLoaded.getGroupId() == InterfaceID.BANKMAIN)
        {
            refreshPrompt();
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage chatMessage)
    {
        ChatMessageType type = chatMessage.getType();
        if (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM)
        {
            return;
        }

        String message = chatMessage.getMessage().replaceAll("<[^>]+>", "");
        String detectedTask = findTaskInMessage(message);
        if (!detectedTask.isEmpty())
        {
            updateTask(detectedTask);
        }
    }

    @Provides
    SlayerSetupPromptConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(SlayerSetupPromptConfig.class);
    }

    private String findTaskInMessage(String message)
    {
        Matcher assignedMatcher = ASSIGNED_PATTERN.matcher(message);
        if (assignedMatcher.find())
        {
            return assignedMatcher.group(1);
        }

        Matcher remainingMatcher = REMAINING_PATTERN.matcher(message);
        if (remainingMatcher.find())
        {
            return remainingMatcher.group(1);
        }

        return "";
    }

    private void saveTask(String task)
    {
        configManager.setConfiguration(SlayerSetupPromptConfig.GROUP, "lastTask", task);
    }

    private String getSelectedTaskThreadSafe()
    {
        if (panel == null)
        {
            return "";
        }

        if (SwingUtilities.isEventDispatchThread())
        {
            return panel.getSelectedTask();
        }

        final String[] selectedTask = {""};
        try
        {
            SwingUtilities.invokeAndWait(() ->
            {
                if (panel != null)
                {
                    selectedTask[0] = panel.getSelectedTask();
                }
            });
        }
        catch (Exception exception)
        {
            return "";
        }

        return selectedTask[0];
    }

    private String cleanTask(String task)
    {
        return task.replaceAll("\\s+", " ").trim();
    }

    private BufferedImage createIcon()
    {
        BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
        java.awt.Graphics2D graphics = image.createGraphics();
        graphics.setColor(new Color(36, 84, 143));
        graphics.fillRoundRect(1, 1, 14, 14, 4, 4);
        graphics.setColor(new Color(235, 235, 235));
        graphics.drawLine(5, 4, 11, 4);
        graphics.drawLine(5, 7, 11, 7);
        graphics.drawLine(5, 10, 9, 10);
        graphics.dispose();
        return image;
    }
}

package com.slayerprompt;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.client.game.ItemManager;

@Singleton
class SlayerSetupPromptSnapshotBuilder
{
    @Inject
    private Client client;

    @Inject
    private ItemManager itemManager;

    String buildPrompt(String task)
    {
        StringBuilder prompt = new StringBuilder(24_000);
        prompt.append("You are an expert Old School RuneScape ironman slayer setup planner.\n");
        prompt.append("Use only the account state below. Give simple, direct instructions.\n\n");
        prompt.append("Goal:\n");
        prompt.append("- Pick the best monster variant/location for this slayer task.\n");
        prompt.append("- Choose worn equipment and inventory from my owned items only.\n");
        prompt.append("- Choose combat style/spell/ammunition and prayers.\n");
        prompt.append("- Prefer ironman-friendly supplies and sustainable choices.\n");
        prompt.append("- If a monster is weak to a specific style or element, use that weakness when my gear/runes support it.\n");
        prompt.append("- Mention any missing unlocks/items that would change the recommendation.\n\n");

        prompt.append("Requested output format:\n");
        prompt.append("1. Task and target variant\n");
        prompt.append("2. Combat style and prayers\n");
        prompt.append("3. Worn equipment\n");
        prompt.append("4. Inventory\n");
        prompt.append("5. Location and method\n");
        prompt.append("6. Short notes\n\n");

        prompt.append("Account context:\n");
        prompt.append("- Account type: Ironman\n");
        prompt.append("- Slayer task: ").append(blankFallback(task, "Unknown / manually select it")).append('\n');
        prompt.append("- Snapshot time: ").append(Instant.now()).append('\n');
        prompt.append("- Player: ").append(blankFallback(client.getLocalPlayer() == null ? "" : client.getLocalPlayer().getName(), "Unknown")).append("\n\n");

        prompt.append("Stats:\n");
        prompt.append(formatStats()).append("\n\n");

        prompt.append("Currently worn equipment:\n");
        prompt.append(formatEquipment()).append("\n\n");

        prompt.append("Current inventory:\n");
        prompt.append(formatContainer(InventoryID.INVENTORY, false, Integer.MAX_VALUE)).append("\n\n");

        prompt.append("Bank contents:\n");
        prompt.append(formatContainer(InventoryID.BANK, true, Integer.MAX_VALUE)).append("\n\n");

        prompt.append("Completed quests:\n");
        prompt.append(formatCompletedQuests()).append('\n');

        return prompt.toString();
    }

    private String formatStats()
    {
        return Arrays.stream(Skill.values())
            .filter(skill -> skill != Skill.OVERALL)
            .map(skill -> "- " + humanize(skill.name()) + ": " + client.getRealSkillLevel(skill)
                + " base, " + client.getBoostedSkillLevel(skill) + " current")
            .collect(Collectors.joining("\n"));
    }

    private String formatEquipment()
    {
        ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
        if (equipment == null)
        {
            return "- Equipment container unavailable.";
        }

        Map<EquipmentInventorySlot, String> slots = new EnumMap<>(EquipmentInventorySlot.class);
        Item[] items = equipment.getItems();
        for (EquipmentInventorySlot slot : EquipmentInventorySlot.values())
        {
            int slotIndex = slot.getSlotIdx();
            if (slotIndex < 0 || slotIndex >= items.length)
            {
                continue;
            }

            Item item = items[slotIndex];
            if (item == null || item.getId() <= 0)
            {
                slots.put(slot, "empty");
                continue;
            }

            slots.put(slot, formatItem(item));
        }

        return slots.entrySet().stream()
            .sorted(Comparator.comparingInt(entry -> entry.getKey().getSlotIdx()))
            .map(entry -> "- " + humanize(entry.getKey().name()) + ": " + entry.getValue())
            .collect(Collectors.joining("\n"));
    }

    private String formatContainer(InventoryID inventoryId, boolean combineStacks, int maxLines)
    {
        ItemContainer container = client.getItemContainer(inventoryId);
        if (container == null)
        {
            return "- " + humanize(inventoryId.name()) + " unavailable. Open the bank and refresh if this should be populated.";
        }

        if (combineStacks)
        {
            Map<String, Long> quantities = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
            for (Item item : container.getItems())
            {
                if (item == null || item.getId() <= 0)
                {
                    continue;
                }

                String name = getItemName(item.getId());
                quantities.merge(name, (long) item.getQuantity(), Long::sum);
            }

            if (quantities.isEmpty())
            {
                return "- Empty or unavailable.";
            }

            List<String> lines = quantities.entrySet().stream()
                .map(entry -> "- " + entry.getKey() + " x" + entry.getValue())
                .limit(maxLines)
                .collect(Collectors.toList());

            int omitted = quantities.size() - lines.size();
            if (omitted > 0)
            {
                lines.add("- ... omitted " + omitted + " additional bank item lines to keep the prompt manageable.");
            }

            return String.join("\n", lines);
        }

        List<String> lines = new ArrayList<>();
        Item[] items = container.getItems();
        for (int i = 0; i < items.length; i++)
        {
            Item item = items[i];
            if (item == null || item.getId() <= 0)
            {
                continue;
            }

            lines.add("- Slot " + (i + 1) + ": " + formatItem(item));
        }

        return lines.isEmpty() ? "- Empty." : String.join("\n", lines);
    }

    private String formatCompletedQuests()
    {
        List<String> completed = new ArrayList<>();
        for (Quest quest : Quest.values())
        {
            try
            {
                if (quest.getState(client) == QuestState.FINISHED)
                {
                    completed.add(quest.getName());
                }
            }
            catch (RuntimeException ignored)
            {
                // Some quest state checks can depend on varbits that are unavailable during login transitions.
            }
        }

        completed.sort(String.CASE_INSENSITIVE_ORDER);
        return completed.isEmpty()
            ? "- No completed quests detected, or quest state is unavailable."
            : completed.stream().map(quest -> "- " + quest).collect(Collectors.joining("\n"));
    }

    private String formatItem(Item item)
    {
        return getItemName(item.getId()) + " x" + item.getQuantity();
    }

    private String getItemName(int itemId)
    {
        ItemComposition composition = itemManager.getItemComposition(itemId);
        String name = composition == null ? "" : composition.getName();
        if (name == null || name.trim().isEmpty() || "null".equalsIgnoreCase(name))
        {
            return "Item " + itemId;
        }

        return name;
    }

    private String humanize(String value)
    {
        String lower = value.toLowerCase().replace('_', ' ');
        StringBuilder builder = new StringBuilder(lower.length());
        boolean capitalizeNext = true;
        for (char character : lower.toCharArray())
        {
            if (Character.isWhitespace(character))
            {
                capitalizeNext = true;
                builder.append(character);
            }
            else if (capitalizeNext)
            {
                builder.append(Character.toUpperCase(character));
                capitalizeNext = false;
            }
            else
            {
                builder.append(character);
            }
        }

        return builder.toString();
    }

    private String blankFallback(String value, String fallback)
    {
        return value == null || value.trim().isEmpty() ? fallback : value.trim();
    }
}

package com.slayerprompt;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class SlayerSetupPromptPluginTest
{
    @Test
    public void configGroupIsStable()
    {
        assertEquals("slayersetupprompt", SlayerSetupPromptConfig.GROUP);
    }

    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(SlayerSetupPromptPlugin.class);
        RuneLite.main(args);
    }
}
